const correctionURL='**/rest/v1/ai_verdict_feedback*';
const correctionSave=page=>page.getByRole('button',{name:'Save correction',exact:true});
const correctionCheck=page=>page.getByRole('button',{name:'Check correction save',exact:true});
const correctionRetry=page=>page.getByRole('button',{name:'Retry same correction',exact:true});
async function correctionForm(page,note='Owner observed metal, not tested alloy'){
 const menu=page.locator('.ci-report-menu');if(!await menu.evaluate(node=>node.open))await page.getByLabel('Report notifications and actions',{exact:true}).click();
 if(!await page.getByRole('region',{name:'Correct AI verdict',exact:true}).isVisible())await page.getByRole('button',{name:'Disagree with verdict',exact:true}).click();
 if(note!==null)await page.getByRole('textbox',{name:'Correction details',exact:true}).fill(note);
}
function correctionWrites(page){const rows=[];page.on('request',r=>{if(r.method()==='POST'&&new URL(r.url()).pathname==='/rest/v1/ai_verdict_feedback')rows.push(r.postDataJSON());});return rows;}
async function corrections(id){const r=await client.from('ai_verdict_feedback').select('*',{count:'exact'}).eq('source_analysis_run_id',id).order('created_at',{ascending:false}).order('id',{ascending:false});expect(r.error).toBeNull();expect(r.count).toBe(r.data.length);return r.data;}
async function correctionSaved(page){await expect(outcome(page)).toContainText('Correction saved and independently read back');await expect(outcome(page)).toBeFocused();await expect(correctionCheck(page)).toHaveCount(0);}
async function originalIntact(run){const row=await source(run.id);for(const key of ['objects','image_manifest','initial_ai_result'])expect(row.result[key]).toEqual(run.original[key]);for(const [index,photo]of run.manifest.entries()){const read=await client.storage.from('item-images').download(photo.storage_path);expect(read.error).toBeNull();expect(digest(Buffer.from(await read.data.arrayBuffer()))).toBe(digest(run.images[index]));}return row;}
